// Complete adapter for all48 nonzero builtin predicate callbacks, composed from independently proved raw bodies.
using System;
namespace Recovered.Gameplay
{
 public sealed class RecoveredAllBuiltinConditions:ScriptConditionServices
 {
  readonly ScriptExpressionServices symbols;readonly ScriptOriginServices origins;readonly ScriptConditionServices remaining;readonly float[] sine;readonly ushort[] angles;
  public RecoveredAllBuiltinConditions(ScriptExpressionServices gameSymbols,ScriptOriginServices gameOrigins,float[] originalSine,ushort[] originalAngles,ScriptConditionServices customPredicates){symbols=gameSymbols;origins=gameOrigins;sine=originalSine;angles=originalAngles;remaining=customPredicates;}
  public override uint Predicate(TakeoverReleaseMemory m,uint callback,uint system,uint packet,uint actor,uint arg14,uint arg18){uint value;if(PreparedBuiltinPredicates.TryEvaluate(m,symbols,callback,system,packet,actor,arg14,arg18,out value))return value;if(PreparedScriptActorPredicates.TryEvaluate(m,callback,packet,actor,arg14,arg18,out value))return value;if(PreparedScriptTriggerPredicates.TryEvaluate(m,callback,system,packet,actor,arg18,out value))return value;switch(callback){case 0x515250:return PreparedScriptCachedRanges.Opponent(m,actor);case 0x515270:return PreparedScriptCachedRanges.NearestOpponent(m,actor);case 0x514aa0:return PreparedScriptLocatorPredicates.RangeY(m,packet,actor,arg18);case 0x515320:return PreparedExactOpponentBelow.Evaluate(m,actor);case 0x514e20:return PreparedScriptNodePredicates.InLevelNode(m,system,actor,arg18);case 0x514e70:return PreparedScriptNodePredicates.PlayerInLevelNode(m,system,arg18);case 0x514ec0:return PreparedScriptNodePredicates.EitherPlayerInLevelNode(m,system,arg18);case 0x514a00:return PreparedScriptSpatialRanges.LocatorRange(m,packet,actor,arg18,false);case 0x514a50:return PreparedScriptSpatialRanges.LocatorRange(m,packet,actor,arg18,true);case 0x514f50:return PreparedScriptSpatialRanges.NodeRange(m,actor,arg18);case 0x514c30:return PreparedScriptPlayerRanges.Player(m,system,actor);case 0x514c80:return PreparedScriptPlayerRanges.Nearest(m,system,actor,false);case 0x514d50:return PreparedScriptPlayerRanges.Nearest(m,system,actor,true);case 0x5154e0:return PreparedScriptOpponentLocator.Evaluate(m,packet,actor,arg18,0);case 0x515530:return PreparedScriptOpponentLocator.Evaluate(m,packet,actor,arg18,1);case 0x515580:return PreparedScriptOpponentLocator.Evaluate(m,packet,actor,arg18,2);case 0x5155c0:return PreparedScriptPlayerLocator.Player(m,system,packet,actor,arg18);case 0x515620:return PreparedScriptPlayerLocator.Nearest(m,system,packet,actor,arg18);case 0x515360:return PreparedScriptOriginRanges.OriginRange(m,origins,system,actor);case 0x5153c0:return PreparedScriptOriginRanges.OpponentToOrigin(m,origins,system,actor);case 0x515450:return PreparedScriptOriginRanges.PlayerToOrigin(m,origins,system,actor);case 0x515290:return PreparedScriptOpponentYaw.Evaluate(m,actor,sine,angles);}if(remaining==null)throw new NotSupportedException("Custom predicate service required for "+callback.ToString("x"));return remaining.Predicate(m,callback,system,packet,actor,arg14,arg18);}
  public override uint Expression(TakeoverReleaseMemory m,uint actor,uint packet,uint text){return PreparedScriptExpressions.Evaluate(m,symbols,actor,packet,text);}
 }
}
